void setup() {
  pinMode(2, INPUT);
  pinMode(13, OUTPUT);
  Serial.begin(9600);
}
void loop() {
  int val = digitalRead(2);
  digitalWrite(13, val);
  if (val) Serial.println("Button Pressed");
  else Serial.println("Button Released");
