  Serial.begin(9600);
  Serial.println("Enter R, G, or B:");
}
void loop() {
  if (Serial.available()) {
    char c = Serial.read();
    digitalWrite(9, LOW);
    digitalWrite(10, LOW);
    digitalWrite(11, LOW);
    if (c == 'R' || c == 'r') {
      digitalWrite(9, HIGH);
      Serial.println("RED ON");
    } else if (c == 'G' || c == 'g') {
    digitalWrite(10, HIGH);
    Serial.println("GREEN ON");
  } else if (c == 'B' || c == 'b') {
  digitalWrite(11, HIGH);
  Serial.println("BLUE ON");
}
}
}

