int ledR = 11;
int ledG = 10;
int ledB = 9;

void setup() {
  pinMode(ledR, OUTPUT);
  pinMode(ledG, OUTPUT);
  pinMode(ledB, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  int val = analogRead(A0);
  float mV = val * 5000.0 / 1024;
  float tempC = (mV - 500) / 10;
  Serial.print(tempC);
  Serial.println("C");

  if (tempC < 20) {
    digitalWrite(ledR, HIGH);
    digitalWrite(ledG, LOW);
    digitalWrite(ledB, LOW);
  } else if (tempC < 30) {
    digitalWrite(ledR, LOW);
    digitalWrite(ledG, HIGH);
    digitalWrite(ledB, LOW);
  } else {
    digitalWrite(ledR, LOW);
    digitalWrite(ledG, LOW);
    digitalWrite(ledB, HIGH);
  }
  delay(500);
}

